import{z as E,x as p,o as n,c,q as s,j as r,D as d,d as o,s as t,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"加载与动态链接","description":"","frontmatter":{"title":"加载与动态链接","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/load-dynlink.md","filePath":"cs/load-dynlink.md","lastUpdated":1791063341000}'),A={name:"cs/load-dynlink.md"};function T(B,a,m,P,L,h){const l=p("Mermaid");return n(),c("div",null,[a[2]||(a[2]=s('<h1 id="加载与动态链接" tabindex="-1">加载与动态链接 <a class="header-anchor" href="#加载与动态链接" aria-label="Permalink to &quot;加载与动态链接&quot;">​</a></h1><div class="epigraph"><p>可执行文件进内存时，加载器映射节并可能再跑一遍重定位；共享库通过 GOT/PLT 把符号绑定推迟到加载或首次调用。</p><footer>—— 据 Levine, Linkers and Loaders, 2000；ELF 与 System V ABI 整理</footer></div><p>上一课<a href="/cs/got-plt">GOT 与 PLT</a>把静态符号填成地址。许多程序还依赖共享库：<code>libc</code> 不进每个可执行文件。本课不重做 <code>ld</code> 的节合并。缺口是：<strong>加载</strong>（把文件变成进程里的映像）与<strong>动态链接</strong>（运行时解析）。进程映像的操作系统细节下一课程才展开；本课从编译产物一侧讲 GOT/PLT。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态链接体积大、修 bug 要重链所有程序。动态：可执行文件带着对 <code>printf</code> 的未决引用。加载时：内核（或用户加载器）按 ELF 程序头 <code>mmap</code> 各段，解释器（<code>ld.so</code>）登场，把依赖库映射进地址空间，填 GOT。延迟绑定：PLT 桩第一次跳进解析器，再改 GOT，其后直跳。</p><p><a href="/cs/paging-vm">虚拟内存分页</a>让不同进程共享库的只读页；本课只要「映射 + 再重定位」，不写缺页。</p><h3 id="动态不是「不链接」" tabindex="-1">动态不是「不链接」 <a class="header-anchor" href="#动态不是「不链接」" aria-label="Permalink to &quot;动态不是「不链接」&quot;">​</a></h3><p>仍要解析符号，只是时刻从编译期挪到加载/首次调用。ABI 仍必须一致：库与可执行文件同一份 psABI，否则参数寄存器错位。</p><p><span class="marginnote">Levine《Linkers and Loaders》给 GOT/PLT 图。ELF <code>DT_NEEDED</code>、<code>R_*_JUMP_SLOT</code> 是机制名字。本课不写动态节全部标签。</span></p><p><span class="marginnote">初学者容易以为「动态链接 = 运行时不用链接」。实际上符号照样要一个一个解析，只是把解析时刻从编译期推迟到加载或首次调用；代价是程序一启动就多了「找库、映射库、填表」这几步，这也是为什么动态链接的程序启动往往比静态的慢一点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>执行：内核读入口，若有 <code>PT_INTERP</code> 则先跑动态链接器。链接器：广度加载依赖、重定位相对型、处理 <code>BIND_NOW</code> 或懒绑定。然后跳到用户入口（CRT 再调 <code>main</code>）。</p><p><span class="marginnote">静态链接意味着每个可执行文件都自带一份库代码：假设 libc 静态链入后让程序多出几 MB，磁盘上 100 个这样的程序就是几百 MB 的重复副本；动态链接整个机器只放一份 libc.so，大家共用，修一个安全漏洞也只需替换这一个文件。</span></p>',13)),(n(),r(i,null,{default:d(()=>[t(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20EXE%5B%22ELF%20%E5%8F%AF%E6%89%A7%E8%A1%8C%22%5D%20--%3E%20MAP%5B%22%E6%98%A0%E5%B0%84%E6%AE%B5%22%5D%0A%20%20MAP%20--%3E%20LD%5B%22ld.so%20%E5%8A%A0%E8%BD%BD%E4%BE%9D%E8%B5%96%22%5D%0A%20%20LD%20--%3E%20GOT%5B%22%E5%A1%AB%20GOT%20%2F%20PLT%22%5D%0A%20%20GOT%20--%3E%20ENT%5B%22%E8%BF%9B%E5%85%A5%E7%94%A8%E6%88%B7%E5%85%A5%E5%8F%A3%22%5D%0A"})]),fallback:d(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("a",{href:"/cs/abi-codegen"},"ABI 代码生成"),o("发出的对外部符号的访问应是 PIC 友好的（"),e("code",null,"auipc"),o("+GOT 等），否则共享库无法任意加载地址。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[o("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"懒绑定的第一次调用值得单独走一遍：程序、PLT 桩、解析器、GOT 各干了什么。第一次多绕一圈查地址，之后全部走捷径。",-1)),(n(),r(i,null,{default:d(()=>[t(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22%E8%B0%83%E7%94%A8%20printf%22%5D%20--%3E%20PLT%5B%22PLT%20%E6%A1%A9%22%5D%0A%20%20PLT%20--%3E%20GOT%7B%22GOT%20%E9%87%8C%E5%B7%B2%E6%9C%89%E5%9C%B0%E5%9D%80%EF%BC%9F%22%7D%0A%20%20GOT%20--%3E%7C%22%E5%90%A6%22%7C%20RES%5B%22%E8%B7%B3%E8%BF%9B%20ld.so%20%E8%A7%A3%E6%9E%90%E5%99%A8%22%5D%0A%20%20RES%20--%3E%20FIND%5B%22%E6%9F%A5%E5%87%BA%20printf%20%E7%9C%9F%E5%AE%9E%E5%9C%B0%E5%9D%80%22%5D%0A%20%20FIND%20--%3E%20PATCH%5B%22%E5%9B%9E%E5%A1%AB%20GOT%22%5D%0A%20%20PATCH%20--%3E%20EXEC%5B%22%E6%89%A7%E8%A1%8C%20printf%22%5D%0A%20%20GOT%20--%3E%7C%22%E6%98%AF%22%7C%20JMP%5B%22%E7%BB%8F%20GOT%20%E7%9B%B4%E8%B7%B3%22%5D%0A%20%20JMP%20--%3E%20EXEC%0A"})]),fallback:d(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">可以把它想象成酒店前台：第一次找某位客人（符号）要翻登记簿（解析器），查到后把房号写在便签上（GOT），以后再找就直接按便签上的房号敲门，不用再翻本子。</span></p><p>PIC：代码不假定自己的绝对加载址，用相对或 GOT。文本段可共享。写 GOT 使数据页私有（写时复制，OS 课再钉）。符号可见性（default/hidden）影响能否被插桩，点名。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写内核 <code>execve</code> 全部、不写容器命名空间。不把动态链接当安全课的 RELRO 清单——可点 ASLR 要 PIC，细节在安全栏。运行时堆与垃圾回收是下一课：加载完成后程序还要分配对象。</p><p>后课默认：进程启动可以经 <code>ld.so</code>；外部 C 符号可懒绑定。运行时与 GC 直觉接在可执行映像已经在内存之后。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>加载映射 ELF 段；动态链接器解析共享库。</li><li>GOT/PLT 把绑定推迟；PIC 使库可装到任意址。</li><li>ABI 必须与库一致。</li><li>出处：Levine, <em>Linkers and Loaders</em>, 2000；ELF；System V / RISC-V psABI。</li></ul>',7))])}const C=E(A,[["render",T]]);export{f as __pageData,C as default};
